import json,pathlib
p=pathlib.Path('src/content')
def write(name,data): (p/f'{name}.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
sources=json.loads((p/'sources.json').read_text())
for id,title,url,supports in [('os-terms','OpenStax · Anatomical terminology','https://openstax.org/books/anatomy-and-physiology-2e/pages/1-6-anatomical-terminology','Directional vocabulary and Figure 1.12, body regions.'),('os-movement','OpenStax · Types of body movements','https://openstax.org/books/anatomy-and-physiology-2e/pages/9-5-types-of-body-movements','Flexion, extension, abduction and adduction.'),('os-nerves','OpenStax · Structure and function of the nervous system','https://openstax.org/books/anatomy-and-physiology-2e/pages/12-1-basic-structure-and-function-of-the-nervous-system','CNS, PNS and the distinction between anatomical and functional divisions; Figure 12.2.'),('yj-warrior','Yoga Journal · Warrior II','https://www.yogajournal.com/poses/warrior-ii-pose/','English and Sanskrit pose names and broad visual identification only; generated art has not been educator-reviewed.')]:
 sources.append({'id':id,'title':title,'url':url,'supports':supports,'retrievedAt':'2026-09-30'})
write('sources',sources)
lessons=[]
def lesson(id,slug,title,mid,topics,goal,sections,sources,reflection,pose=False,tradition=False):
 d={'id':id,'slug':slug,'title':title,'primaryModuleId':mid,'topicIds':topics,'goal':goal,'sections':[{'heading':h,'text':t} for h,t in sections],'activityIds':[],'relatedPoseIds':['warrior-ii'] if pose else [],'sourceIds':sources,'publication':'draft','review':{'status':'unreviewed'},'reflection':reflection}
 if tradition:d['traditionLabel']='Traditional yoga framework; not biomedical anatomy'
 lessons.append(d)
lesson('practice-map','your-practice-vocabulary','A place for each part of practice','M1',['M1-T01','M1-T06','M1-T10'],'Organise what you hear in class into a few familiar study categories.',[
 ('Three places to begin','Yoga teacher training can include posture study, breathing techniques and meditation. Use these as three headings in your notebook. The outline names more practices too; your teacher can tell you how they fit into your cohort.'),
 ('Capture the class, in your own words','After class, choose one thing you remember under each heading. Write what the teacher called it, what you noticed, and what remains unclear. Leave a blank where you do not remember; that blank becomes a useful question.'),
 ('A small learning ritual','Pick one entry to explain aloud in one sentence. Check your wording against your class notes, then save the correction. You are building a personal vocabulary, one class at a time.')],['training-outline'],'Which practice term would you like your teacher to explain again?')
lesson('body-language','read-the-body','Read the body, one word at a time','M2',['M2-T01'],'Use a few directional terms to read an anatomy diagram with confidence.',[
 ('Give the picture an orientation','Anatomical terminology uses a standard reference position. Directional terms refer to the person’s body, rather than your position looking at a picture.'),
 ('Find the useful pairs','Anterior means toward the front; posterior means toward the back. Medial points toward the body’s midline, and lateral away from it. Proximal means closer to the limb’s attachment, while distal means farther from it.'),
 ('Try a small comparison','The elbow is proximal to the wrist. Turn that relationship around: the wrist is distal to the elbow. Say both sentences, then locate the regions on the reference diagram.')],['os-terms'],'What anatomical word could replace “over here” in one of your class notes?',True)
lesson('movement-words','describe-a-movement','Describe a movement','M2',['M2-T03'],'Distinguish four movement terms you may hear in anatomy class.',[
 ('Bending and straightening','At the elbow and knee, flexion reduces the angle between the bones. Extension increases it. Always name the joint you are describing.'),
 ('Away and toward','Abduction moves a limb away from the body’s midline; adduction brings it toward the midline. Raising an arm out to the side is an example of shoulder abduction.'),
 ('Turn observation into a question','In the Warrior II illustration, find the bent knee. Write down the movement term it reminds you of, then ask your teacher to connect the vocabulary to the pose as taught in class.')],['os-movement'],'Which pair of movement words is easiest to confuse?',True)
lesson('nervous-basics','meet-your-nervous-system','Meet your nervous system','M2',['M2-T15'],'Separate the system’s main anatomical divisions from descriptions of what it does.',[
 ('Two anatomical divisions','The central nervous system (CNS) includes the brain and spinal cord. The peripheral nervous system (PNS) includes nerves and ganglia beyond them.'),
 ('Structure and function ask different questions','Sensation, integration and response describe functions. CNS and PNS describe anatomical organisation. One is not a replacement for the other.'),
 ('Bring it back to class','Make a two-column note: structures on the left, functions on the right. Ask your teacher which additional terms your course expects. This introduction makes no claim that a particular pose treats or resets a nerve.')],['os-nerves'],'What is one distinction you can now explain without looking?')
lesson('energy-context','energy-in-yoga-traditions','Energy concepts, in context','M2',['M2-T06','M2-T07'],'Keep a clear record of the framework your teacher is using.',[
 ('Name the framework','The course outline includes chakras and nadis under energy anatomy. Study these within the yoga tradition and interpretation your teacher presents. They are not labels for anatomical organs or peripheral nerves.'),
 ('A source-aware notebook','Create three columns: term, the explanation given in class, and its text or tradition. If a diagram appears, record its source before copying the labels.'),
 ('Ask for the connection','Write one question about how the teacher uses this framework in practice. Keep that discussion separate from your biomedical anatomy glossary.')],['training-outline'],'Which text or tradition supports the energy model being taught?',tradition=True)
lesson('clear-cues','find-your-teaching-voice','Find your teaching voice','M3',['M3-T01','M3-T07'],'Turn an observation from class into a cue to discuss with your teacher.',[
 ('Listen before you edit','Choose a cue you heard in class. Write it down and note what happened next. Did the teacher demonstrate, pause, or rephrase it? Describe only what you could observe.'),
 ('One intention, two versions','Write a shorter version of the cue, then one that uses different words. Read both aloud. Ask a peer what action each version suggests, without assuming their response will match yours.'),
 ('Bring the draft to your teacher','Save the cue and a question about it. An educator can help check the wording, appropriateness and timing. This exercise is a sample writing activity, not reviewed practical instruction.')],['training-outline'],'What did you notice about how your teacher checked that a cue was understood?')
lesson('ethics-reflection','reflection-in-relationships','Reflection in relationships','M4',['M4-T08','M4-T09'],'Use a classroom scenario to practise thoughtful questions about teacher–student relationships.',[
 ('Consider a moment','Imagine a student declines an optional class activity. Before writing a response, list what you know and what you are only assuming about their choice.'),
 ('Make room for a perspective','Draft a response that acknowledges the student’s words. What would you ask privately, and what should remain theirs to share or keep? Take the scenario to your teacher to discuss professional boundaries.'),
 ('Connect to your reading','The public course outline includes ethics and traditional texts. Add the text, passage, translation and explanation used in your own class before linking this scenario to a philosophical idea.')],['training-outline'],'How would you respect a student’s choice while keeping the group informed?')
lesson('feedback-loop','a-small-teaching-rehearsal','One rehearsal, one next step','M5',['M5-T01','M5-T02','M5-T03'],'Prepare a short rehearsal and a useful feedback question.',[
 ('Choose a familiar excerpt','Use a sequence your teacher has already taught. In the rehearsal tool, add the poses you can select and keep any other sequence details in your notes. Enter the cue and time you want to practise for each step.'),
 ('Observe something specific','Ask a peer to listen for one thing: a pause, clarity of wording, or the timing of a transition. They can write what they heard before offering an interpretation.'),
 ('Close the loop','Record one thing to keep and one thing to change. Rehearse again and compare the two attempts. This is a personal feedback routine; the school’s practicum and written exam have their own requirements.')],['training-outline'],'Which one part of your next rehearsal would you like feedback on?')
lesson('pose-observation','observe-a-pose','Observe before you explain','M1',['M1-T01'],'Describe the Warrior II illustration and save a question for class.',[
 ('Recognise the example','The pose library begins with Warrior II, also called Virabhadrasana II. In the draft illustration, one knee is bent, the opposite leg is straight, and the arms extend to either side.'),
 ('Look without prescribing','Notice the shoulder, hip and knee markers. These are landmarks for discussion, not precise anatomical overlays or a prescription for how every body should look.'),
 ('Keep your teacher’s words','Write the cue your teacher gives for this pose. Add a question about anything that does not make sense yet. Cues, variations and animated demonstrations will need educator review before this becomes practical instruction.')],['yj-warrior'],'What would you ask your teacher about this pose?',True)
write('lessons',lessons)
topics=json.loads((p/'topics.json').read_text())
for t in topics:t['lessonIds']=[l['id'] for l in lessons if t['id'] in l['topicIds']]
write('topics',topics)
bodyimg='https://openstax.org/apps/image-cdn/v1/f%3Dwebp/apps/archive/20260604.144757/resources/83c2b51d5892328f3e0352519cfc434c867247e8'
nerveimg='https://openstax.org/apps/image-cdn/v1/f%3Dwebp/apps/archive/20260604.144757/resources/37beec4ad5ed1d7d66aa510af01f5abf5d0070c8'
terms=next(s['url'] for s in sources if s['id']=='os-terms');nerves=next(s['url'] for s in sources if s['id']=='os-nerves')
regions=[]
for id,title,desc,detail,prompt,answer in [('shoulder','Shoulder','A familiar starting point for the upper limb.','Locate the shoulder region on the front and back views. Compare it with the elbow and wrist.','Which is closer to the shoulder: elbow or wrist?','The elbow is proximal to the wrist: closer to the limb’s attachment.'),('hip','Hip','Notice where the trunk meets the lower limb.','Locate the hip region in the reference diagram. Use the picture to practise naming regions, rather than estimating a person’s range of movement.','What does “medial” mean?','Toward the body’s midline.'),('knee','Knee','Connect a visible bend with movement vocabulary.','Compare a bent knee and a straightened knee in the pose illustration.','What is the movement term for bending the knee?','Flexion. At the knee, it reduces the angle between the bones.')]:
 regions.append({'id':id,'slug':id,'title':title,'kind':'region','description':desc,'heading':'Locate it. Then name it.','detail':detail,'prompt':prompt,'answer':answer,'image':bodyimg,'imageAlt':'OpenStax anatomical position diagram with front and back views and labelled body regions.','sourceUrl':terms,'sourceIds':['os-terms','os-movement'],'lessonSlug':'describe-a-movement' if id=='knee' else 'read-the-body','lessonId':'movement-words' if id=='knee' else 'body-language'})
regions.append({'id':'nervous','slug':'nervous-system','title':'The nervous system','kind':'system','description':'Begin with the central and peripheral divisions.','heading':'Two divisions, one connected system.','detail':'CNS and PNS describe anatomical organisation. Sensation, integration and response describe functions. Keep those two kinds of description distinct.','prompt':'Which structures make up the CNS?','answer':'The brain and spinal cord.','image':nerveimg,'imageAlt':'OpenStax diagram distinguishes the brain and spinal cord of the central nervous system from peripheral nerves and ganglia.','sourceUrl':nerves,'sourceIds':['os-nerves'],'lessonSlug':'meet-your-nervous-system','lessonId':'nervous-basics'})
regions.append({'id':'tradition','slug':'yoga-traditions','title':'Energy concepts','kind':'tradition','description':'A separate collection for the traditional frameworks discussed in class.','heading':'Let the tradition give it context.','detail':'Chakras and nadis belong to traditional frameworks. Record your teacher’s text and interpretation alongside the terms. Keep these notes distinct from the biomedical body map.','prompt':'What source would you record with a traditional diagram?','answer':'Name the text or tradition, and the interpretation used by your teacher. There is no single answer to score here.','sourceIds':['training-outline'],'lessonSlug':'energy-in-yoga-traditions','lessonId':'energy-context'})
write('regions',regions)
write('poses',[{'id':'warrior-ii','slug':'warrior-ii','englishName':'Warrior II','sanskritName':'Virabhadrasana II','aliases':['Warrior 2','Virabhadrasana 2','Vīrabhadrāsana II'],'regionIds':['shoulder','hip','knee'],'lessonIds':['pose-observation','movement-words','body-language'],'illustrationAssetId':'warrior-ii','anatomyAssetIds':['os-regions'],'cues':[],'variations':[],'sourceIds':['yj-warrior','os-movement'],'review':{'status':'unreviewed'}}])
assets=[{'id':'warrior-ii','path':'/assets/warrior-ii.png','source':'OpenAI built-in image generation, 2026-09-30','rights':'Generated for this project from selected design reference.','intendedUse':'Decorative sample pose observation; not validated practical instruction.','review':{'status':'unreviewed'},'prompt':'Full-body purple-haired woman in Warrior II, clay crop tank, sage leggings, lavender circle and sage foliage on ivory background. No labels or UI. Reference: design/quiet-studio-selected.png.'},{'id':'os-regions','url':bodyimg,'source':terms,'rights':'OpenStax Anatomy and Physiology 2e, Figure 1.12, CC BY 4.0, unmodified remote image.','intendedUse':'Authoritative body-region diagram.','review':{'status':'source-inspected','reviewer':'Codex source comparison','date':'2026-09-30'}},{'id':'os-nervous','url':nerveimg,'source':nerves,'rights':'OpenStax Anatomy and Physiology 2e, Figure 12.2, CC BY 4.0, unmodified remote image.','intendedUse':'CNS/PNS reference diagram.','review':{'status':'source-inspected','reviewer':'Codex source comparison','date':'2026-09-30'}}]
pathlib.Path('content-review/asset-register.json').write_text(json.dumps(assets,indent=2)+'\n')
